import numpy as np
f=np.float32
def dot(a,b):return f(f(a[0]*b[0]+a[1]*b[1])+a[2]*b[2])
def mv(K,x):return (K[:,0]*x[0]+K[:,1]*x[1])+K[:,2]*x[2]
def solve(K,b):
 a,c,d=K.T;det=dot(a,np.cross(c,d))
 if abs(det)<=1.17549435e-35:return np.zeros(3,dtype=np.float32)
 return np.array([dot(b,np.cross(c,d)),dot(np.cross(d,a),b),dot(np.cross(a,c),b)],dtype=np.float32)/det
def clamp(x,r):
 length=f(np.sqrt(dot(x,x)));return x*f(r/length) if length>r else x

def project(K,cdot,old,r):
 n=len(old);A=np.eye(3,dtype=np.float32);A[:n,:n]=np.array(K,dtype=np.float32);A=f(.5)*(A+A.T);old3=np.zeros(3,dtype=np.float32);old3[:n]=old;rhs=np.zeros(3,dtype=np.float32);rhs[:n]=cdot;r=f(r)
 if r<=0:return np.zeros(n),dict(branch='zero')
 g=rhs-mv(A,old3);unconstrained=solve(A,-g)
 if dot(unconstrained,unconstrained)<=r*r:return unconstrained[:n].astype(float),dict(branch='free')
 low=f(0);high=f(np.sqrt(dot(g,g))/r)
 for iteration in range(24):
  mid=f(.5)*f(low+high);x=solve(A+mid*np.eye(3,dtype=np.float32),-g)
  if dot(x,x)>r*r:low=mid
  else:high=mid
 x=clamp(solve(A+high*np.eye(3,dtype=np.float32),-g),r);feasible=clamp(old3,r);value=f(f(.5)*dot(x,mv(A,x))+dot(g,x));oldvalue=f(f(.5)*dot(feasible,mv(A,feasible))+dot(g,feasible));fallback=bool(value>oldvalue)
 return (feasible if fallback else x)[:n].astype(float),dict(branch='fallback' if fallback else 'metric',candidate_value=float(value),old_value=float(oldvalue),candidate=x[:n].astype(float).tolist())

