from pathlib import Path
import sys,json,numpy as np
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-coupled-reference'))
import model as m
from wave import ops,solve_pair
from projection import project
capture=json.loads((p.parent/'rain-reference-exact-separation/result.json').read_text());blocks={json.dumps(b['label'][1])+':'+str(b['label'][3]):b for b in m.blocks if b['label'][0]=='contact' and b['label'][2]=='normal'}
for rec in capture['separations']:blocks[json.dumps(rec['identity'])+':'+str(rec['point'])]['bias'][:]=rec['exact_bias']
m.bias=np.concatenate([b['bias'] for b in m.blocks]);m.g=m.J@m.vfree+m.bias
for op in ops:op['bias']=m.bias[op['indices']]
rng=np.random.default_rng(20260930);controls=[]
for i in range(24):
 Q,_=np.linalg.qr(rng.normal(size=(3,3)));K=(Q@np.diag(10**rng.uniform(-1,2,3))@Q.T).astype(np.float32);cdot=rng.normal(size=3).astype(np.float32);old=np.zeros(3,dtype=np.float32);cap=np.float32(10**rng.uniform(-2,0));got,_=project(K,cdot,old,cap);want=m.metric_project(K.astype(float),cdot.astype(float),float(cap));err=float(np.linalg.norm(got-want)/max(float(cap),np.linalg.norm(want)));excess=max(0,float(np.linalg.norm(got)/cap-1));assert err<2e-5 and excess<2e-7;controls.append(dict(error=err,excess=excess))
state=np.load(p.parent/'rain-reference-wave-fidelity/comparison.npz');actual=state['actual_impulses'];actualv=state['actual_velocity'];rel=lambda a,b:abs(a-b)/(1+np.maximum(abs(a),abs(b)));arms={}
for mode in ['predicted','actual-prior']:
 x=m.old.copy();velocity=m.vcap.copy();rows=[]
 for b in ops:
  ii=b['indices'];before=x[ii].copy();grad=b['J']@velocity+b['bias']+b['G']@before;K=b['K']+b['G'];new=before-b['inverse']@grad;info={}
  if b['domain']=='positive':new=np.maximum(new,0)
  elif b['domain']=='positive_pair':new=solve_pair(K,grad-K@before)
  elif b['domain']=='box':new=np.clip(new,-m.radius(b,x),m.radius(b,x))
  elif b['domain']=='ball':new,info=project(K,grad,before,m.radius(b,x))
  rows.append(dict(label=b['label'],error=float(max(rel(new,actual[ii]))),predicted=new.tolist(),actual=actual[ii].tolist(),before=before.tolist(),projection=info))
  if mode=='actual-prior':new=actual[ii]
  velocity+=b['B']@(new-before);x[ii]=new
 ie=float(max(rel(x,actual)));ve=float(max(rel(velocity,actualv)));arms[mode]=dict(maximum_relative_impulse_error=ie,maximum_relative_velocity_error=ve,maximum_local_error=max(r['error'] for r in rows),fallbacks=sum(r['projection'].get('branch')=='fallback' for r in rows),rows=rows)
 np.savez(p/(mode+'.npz'),impulses=x,velocities=velocity)
result=dict(status='hybrid-fidelity-pass' if max(arms['predicted']['maximum_relative_impulse_error'],arms['predicted']['maximum_relative_velocity_error'])<=2e-5 else 'hybrid-fidelity-failed',controls=controls,arms=arms,scope='CPU float32 ball projection only; other arithmetic and reconstructed geometry remain float64. No whole-shader float32/physical qualification.')
(p/'result.json').write_text(json.dumps(result,indent=2));print(json.dumps(dict(status=result['status'],controls_max_error=max(r['error'] for r in controls),arms={k:{a:b for a,b in v.items() if a!='rows'} for k,v in arms.items()}),indent=2))
if result['status']!='hybrid-fidelity-pass':raise SystemExit(1)
